          "text": "<p class=\"prose-p\"><span class=\"para-ref\">[1.2]</span> Roman engineers solved town water shortages using gravity. Because local rivers grew fouled with urban filth, engineers surveyed distant hill and mountain springs to bring pure upland water into growing towns.</p><p class=\"prose-p\">They built giant stone **aqueducts** along a gentle, measured downward slope that carried millions of gallons into **castella** water towers. From these storage tanks, lead and clay pipes sent flowing water across town to public street fountains, communal **thermae** baths, and rich private villas.</p>",
