          "act": 5,
          "title": "Historical Verdict: Romanitas, Imperial Prestige & The AD 410 Collapse",
          "theme_heading": "Historical Verdict: Romanitas, Imperial Prestige & The AD 410 Collapse",
          "text": "<p class=\"prose-p\"><span class=\"para-ref\">[1.5]</span> Modern historians see Roman **sanitation** as a symbol of imperial power and pride rather than true germ science. Governors built giant aqueducts and marble baths mainly to show off **Romanitas** and civilised prestige across newly conquered lands.</p><p class=\"prose-p\">The fatal weakness of Roman hygiene was its total dependence on centralized imperial administration. When Roman legions left Britain in **AD 410**, skilled upkeep collapsed, leaving a thousand-year sanitation gap as stone aqueducts crumbled into weeds and rubble.</p>",
