          "model_answer": "A primary reason the Romans built sophisticated water systems was the need to supply clean drinking water to crowded new towns like Londinium. Engineers constructed stone aqueducts to channel fresh water from distant springs directly into public fountains, bathhouses, and flushing latrines. This prevented deadly water-borne diseases like dysentery in dense urban areas.<br><br>Furthermore, monumental bathhouses were built to project imperial power and spread Roman culture (Romanitas). Grand public baths with heated hypocausts encouraged Celtic Britons to adopt Roman hygiene and civilized daily habits, showing off the superior wealth and engineering of the Roman Empire.",
