          "title": "The Medieval Borough Boom & Overhanging Jetties",
          "theme_heading": "The Medieval Borough Boom & Overhanging Jetties",
          "text": "<p class=\"prose-p\"><span class=\"para-ref\">[2.1]</span> After the Roman legions left Britain in AD 410, old stone aqueducts and town drains fell into ruin. As Anglo-Saxons and Normans rebuilt England, people settled along river crossings and walled market towns called **boroughs**. By the twelfth century, thousands of traders crowded along narrow, unpaved muddy lanes.</p><p class=\"prose-p\">Early medieval boroughs had no central sewers, so messy trades worked right in the street. Butchers slaughtered cattle outside their shops and tossed offal into gutters, while tanners soaked hides in vats of foul urine. Dyers poured toxic cloth dyes straight into rivers used downstream for drinking water.</p>",
