          "title": "Monastic Hydraulics: Canterbury Priory’s Five Settling Tanks (c.1165)",
          "theme_heading": "Monastic Hydraulics: Canterbury Priory’s Five Settling Tanks (c.1165)",
          "text": "<p class=\"prose-p\"><span class=\"para-ref\">[2.3]</span> Medieval monasteries were far cleaner than crowded market towns. Rich religious houses laid **lead conduits** and stone **settling tanks**. Pure hilltop spring water flowed straight into kitchens, infirmaries, and washbasins (**lavatorium**).</p><p class=\"prose-p\">Monks lived inside quiet walled cloisters away from town crowds. At **Canterbury Priory**, water passed through five successive settling tanks to trap grit before running water flushed the latrines clean. Sites like **Titchfield Abbey** also kept clean fishponds, blending Church wealth with careful engineering.</p>",
