          "content": "<p class=\"prose-p\"><span class=\"para-ref\">[2.4]</span> In summer **1348**, a terrible plague struck Britain: the **Black Death**. Caused by the bacterium <em>Yersinia pestis</em> carried on flea-infested black rats, it killed 30% to 50% of Britain's people in eighteen months. Medieval doctors did not know about germs, so they blamed the stars, God's anger, and foul air (**miasma**).</p><p class=\"prose-p\">Even so, town councils tried hard to fight the **epidemic**. Ports held incoming ships for forty-day quarantines (<em>quarantena</em>), and towns barred travellers from infected areas. In London, churchyards filled within weeks, forcing workers to dig deep mass burial trenches at Smithfield and East Smithfield.</p>"
