          "model_answer": "A primary reason towns had worse public health was severe overcrowding and the lack of clean piped water. Towns like London had unpaved streets where butchers dumped animal waste, and porous cesspits frequently leaked sewage into drinking wells, causing deadly outbreaks of cholera and dysentery.<br><br>In contrast, wealthy monasteries were planned with advanced water systems. Priories like Canterbury had clean spring water piped through underground lead conduits into settling tanks and washbasins (lavatoria). Monks followed strict rules requiring cleanliness, while towns had no central planning, meaning urban waste was dumped into local rivers.",
