          "viewing_task": "<ol><li><strong>[00:45] Recall:</strong> What was a medieval 'gong farmer' paid to dig out, and why were they only allowed to work at night?</li><li><strong>[02:15] Explain:</strong> Explain two dangers gong farmers faced from asphyxiating gases and collapsing cesspits—and why they were paid relatively high wages despite low status.</li><li><strong>[03:50] Challenge:</strong> Does the existence of paid gong farmers and town fines prove medieval people cared about cleanliness, or show why medieval infrastructure failed?</li></ol>",
          "model_answer": "<ol><li><strong>Recall:</strong> They emptied human waste from household privies and stone-lined cesspits, working strictly at night (often 9 p.m. to 5 a.m.) to spare townspeople the foul smell and miasma.</li><li><strong>Explain:</strong> Workers risked suffocating on toxic methane/ammonia fumes or drowning if rotten floorboards collapsed (like Richard the Raker in 1326), so boroughs had to pay high wages to attract workers.</li><li><strong>Challenge:</strong> It proves medieval townspeople disliked filth and passed laws to manage waste, but without Roman-style pressurized sewers, porous cesspits still leaked sewage straight into nearby drinking wells.</li></ol>"
