          "content": "<p class=\"prose-p\"><span class=\"para-ref\">[3.2]</span> In **1596**, **Queen Elizabeth I**'s godson **Sir John Harington** invented the first flushing **water closet**. He nicknamed it the 'Ajax' in his book <em>The Metamorphosis of Ajax</em>. Harington fitted a working model at **Richmond Palace**, using a brass valve and cistern to wash waste into a vault below.</p><p class=\"prose-p\">Yet Harington's clever invention failed to change Tudor towns. Because streets had no pressurized water mains or underground sewers, the flush toilet stayed a rare royal toy. Ordinary Elizabethans went on using chamber pots and wooden close-stools for another two hundred years.</p>"
