              "caption": "Original copper etching depicting the Water House and reservoir basins at New River Head, Islington, engineered between 1609 and 1613 by Sir Hugh Myddelton to supply fresh water to London (British Museum / Yale Center for British Art).",
              "author": "Wenceslaus Hollar, Bohemian-English Printmaker",
              "date": "1665",
              "question_badge": "17TH-CENTURY HYDRAULIC INFRASTRUCTURE",
