              "model_answer": "Source C shows the New River Head reservoir basin and two-storey Water House in Islington, where fresh water brought by a 38-mile canal was impounded and fed into wooden gravity pipes. This proves that large-scale civil engineering was used to supply fresh water to the growing capital.",
              "context": "Completed in 1613 with financial backing from King James I, the New River brought spring water from Chadwell and Amwell to Islington, where wooden elm-trunk pipes carried water to paying subscribers.",
