          "context": "Published by British satirist John Leech in the reformist middle-class magazine Punch following London’s second cholera pandemic of 1848–49. The cartoon depicts an unpaved slum court dominated by a coffin merchant, a child playing on a dungheap, and raw sewage seeping from broken privies.",
