      "tasks": [
        {
          "id": "ws_l4_q2_explain_why",
          "type": "extended_writing",
          "topic": "Extended Historical Writing • Causal Explanation (2–3 Paragraphs • 15 mins)",
          "title": "Extended Historical Writing • Causal Explanation (2–3 Paragraphs • 15 mins)",
          "question": "Explain why living conditions and public health in British boomtowns worsened dramatically during the Industrial Revolution.",
          "stimulus": [
            "The rapid construction of unventilated back-to-back housing and shared privy middens",
            "The arrival of Asiatic cholera in 1831 and the persistence of miasma theory"
          ],
          "scaffolding": {
            "guidance": "Write a structured 3-paragraph PEEL response. Use the exact words from the question stem in your Point and in your Link for every paragraph.",
            "structure_strip": [
              {
                "col": "1. INDUSTRIAL URBANISATION & SQUALOR",
                "prompt": "Explain how steam-powered factories caused population explosion and flimsy back-to-back tenements with zero municipal drainage [4.1].",
                "starter": "A primary catalyst explaining why living conditions in British boomtowns worsened was rapid industrial urbanisation and speculative building..."
              },
              {
                "col": "2. ASIATIC CHOLERA & MIASMA DOGMA",
                "prompt": "Explain how the 1831 Asiatic cholera epidemic struck and why belief in airborne miasma delayed clean water interventions [4.2, 4.3].",
                "starter": "Furthermore, a decisive reason explaining why public health deteriorated was the terrifying arrival of Asiatic cholera in 1831..."
              },
              {
                "col": "3. LAISSEZ-FAIRE INERTIA & VERDICT",
                "prompt": "Explain how ratepayer opposition and laissez-faire politics blocked Chadwick's 1848 Public Health Act until the 1858 Great Stink [4.3, 4.4].",
                "starter": "Ultimately, the decisive underlying reason why squalor persisted was the prevailing government philosophy of laissez-faire..."
              }
            ],
            "sentence_starters": [
              "A primary catalyst explaining why living conditions in British boomtowns worsened was...",
              "Specifically, this meant that...",
              "In particular, this was demonstrated when...",
              "Consequently, this reveals that...",
              "Ultimately, the decisive reason why public health deteriorated was... because..."
            ],
            "model_answer": "A primary catalyst explaining why living conditions in British boomtowns worsened was rapid industrial urbanisation and speculative building. Between 1780 and 1850, the Industrial Revolution concentrated millions of factory workers into northern cities like Manchester, which grew tenfold. Speculative landlords threw up unventilated back-to-back tenements sharing party walls on three sides, with raw sewage draining into unpaved streets from shared privy middens. Consequently, this explosive urban growth directly triggered lethal outbreaks of typhus and contaminated shallow drinking wells.\n\nFurthermore, a decisive reason explaining why public health deteriorated was the arrival of Asiatic cholera in 1831 combined with widespread medical ignorance. When cholera struck Sunderland in October 1831, killing over 52,000 Britons in months, doctors remained convinced that atmospheric miasma was the vector. Because authorities burned tar barrels rather than isolating water contamination, the disease spread unchecked through dense slums where privies leaked directly into drinking water sources.\n\nUltimately, the decisive underlying reason why squalor persisted was the prevailing government philosophy of laissez-faire. Although Edwin Chadwick's 1842 Report proved that filthy slums caused poverty and disease, wealthy ratepayers resisted paying municipal taxes for glazed sewer pipes. The resulting 1848 Public Health Act was permissive rather than compulsory, ensuring that until the 1858 Great Stink threatened Parliament directly, local councils refused to fund the infrastructure needed to save working-class lives."
          },
          "model_answer": "A primary reason was the rapid, uncontrolled growth of industrial factory towns. Between 1800 and 1850, thousands of workers moved to cities like Manchester and Leeds. Greedy landlords built cramped, unventilated back-to-back houses with no piped water or drainage. Up to a hundred people often shared a single overflowing privy.<br><br>Furthermore, governments followed a strict laissez-faire policy, refusing to spend taxpayers' money on public sanitation. With no clean piped water, sewage seeped into local rivers and pump wells. Consequently, when cholera struck Britain in 1831, it spread rapidly through contaminated water, killing thousands of factory workers.",
          "model": "A primary reason was the rapid, uncontrolled growth of industrial factory towns. Between 1800 and 1850, thousands of workers moved to cities like Manchester and Leeds. Greedy landlords built cramped, unventilated back-to-back houses with no piped water or drainage. Up to a hundred people often shared a single overflowing privy.<br><br>Furthermore, governments followed a strict laissez-faire policy, refusing to spend taxpayers' money on public sanitation. With no clean piped water, sewage seeped into local rivers and pump wells. Consequently, when cholera struck Britain in 1831, it spread rapidly through contaminated water, killing thousands of factory workers."
        }
      ],
