          "model_answer": "Snow used the brewery anomaly to disprove miasma theory by showing that people breathing the exact same foul Soho air survived completely unscathed if they did not swallow pump water. Because the 70 draymen and maltsters drank only fermented beer and possessed a private well on site, their total immunity provided positive proof that cholera was ingested through contaminated drinking water.",
          "context": "Published by Dr John Snow in On the Mode of Communication of Cholera (London: John Churchill, 1855). Snow documented how 70 workers in the Lion Brewery on Broad Street escaped cholera entirely because their employer supplied them with free beer, preventing them from drinking water from the contaminated pump.",
