          "type": "written",
          "title": "Source C: Reverend Henry Whitehead's Vestry Report on the 40 Broad Street Cesspool (1855)",
          "author": "Reverend Henry Whitehead (Curate of St Luke's, Soho)",
          "date": "1855",
          "text": "\"I ascertained that an infant residing at No. 40 Broad Street had been attacked with diarrhoea on 28th August and died on 2nd September. The mother informed me that the soiled cloths and wash-water had been emptied into the cesspool in the cellar at the front of the house. Upon excavating the soil, the brickwork of the cesspool was discovered to be decayed and fractured, its liquid contents percolating directly through two feet eight inches of porous earth into the well of the Broad Street pump... This untoward circumstance solved the whole mystery of the outbreak, confirming Dr Snow’s conclusion beyond any doubt.\"",
          "source_context": "Written by Reverend Henry Whitehead in the Report of the St James Vestry Cholera Inquiry Committee (1855). Whitehead originally believed in miasma and set out to disprove Dr John Snow’s water theory, but his thorough house-to-house pastoral interviews uncovered the index case and the physical breach between the cesspool and the well.",
          "model_answer": "Source C proves that cholera entered the Broad Street drinking well through physical contamination from an adjacent domestic cesspool at No. 40 Broad Street. The washing of an infected infant’s soiled linen drained into decayed brickwork, allowing lethal fecal matter to seep directly into the pump water consumed by local residents.",
          "context": "Written by Reverend Henry Whitehead in the Report of the St James Vestry Cholera Inquiry Committee (1855). Whitehead originally believed in miasma and set out to disprove Dr John Snow’s water theory, but his thorough house-to-house pastoral interviews uncovered the index case and the physical breach between the cesspool and the well.",
          "teacher_notes": {
            "hinge_question": "Why was Reverend Whitehead’s collaboration vital in convincing a sceptical medical establishment of Snow’s waterborne discovery?"
          },
