          "caption": "Diagram illustrating Louis Pasteur's famous swan-neck flask experiments disproving spontaneous generation and demonstrating airborne microbial contamination.",
          "image": "/images/pasteur_swan_neck.jpg",
          "source_context": "Published by French chemist Louis Pasteur in his 1861 treatise Mémoire sur les corpuscules organisés qui existent dans l'atmosphère. Pasteur demonstrated that nutrient broth remained sterile when curved flask necks trapped falling airborne dust particles, but fermented rapidly when the necks were broken.",
          "model_answer": "Source D demonstrates that living microbes enter liquids from external atmospheric dust rather than generating spontaneously from rotting matter. By showing that boiled broth remained sterile indefinitely inside unbroken curved flasks, Pasteur proved that specific biological micro-organisms—not bad smells—caused decomposition and disease.",
