          "model_answer": "A primary factor driving rapid progress was scientific discovery. In 1854, Dr John Snow proved cholera was water-borne by mapping Soho deaths around the Broad Street pump. Later, Louis Pasteur’s 1861 Germ Theory proved microbes caused disease, convincing authorities that pure drinking water was essential for saving lives.<br><br>Furthermore, government attitudes shifted away from laissez-faire toward compulsory state action. After Bazalgette constructed London’s massive sewer network, Disraeli’s government passed the landmark 1875 Public Health Act. This forced local councils to provide clean piped water, collect rubbish, and build covered sewers, transforming medical knowledge into national sanitation.",
