      "extract": "\"For more than four hundred years after Rome was founded, our citizens drank muddy water drawn from the River Tiber or local wells. Today, nine great stone aqueducts carry pure mountain spring water into our city. Driven solely by gentle gravity, the water flows through rock tunnels and across high arched bridges day and night.\"\n\n\"As Water Commissioner of Rome, I have walked and inspected every mile of these channels myself. Near the city walls, each aqueduct passes through deep stone settling tanks. There, pebbles and river mud sink to the bottom so the water enters our pipes clear and sweet.\"\n\n\"Inside Rome, public fountains supply rich senators and poor street-sellers alike. Great bathhouses steam with hot water, while army forts enjoy clean drinking supplies. Even the overflow water from the fountains is never wasted. Day and night, it rushes beneath the streets through the great Cloaca Maxima sewer, scouring away the filth and bad smells that once bred sickness.\"\n\n\"Look at all these practical structures serving millions of lives. Go ahead and compare them, if you dare, with the idle Pyramids of Egypt!\"",
