      "extract": "\"7 June 1665: Today, much against my will, I walked down Drury Lane in fierce summer heat. On two or three doors I saw a bright red cross painted a foot high, with the words: 'Lord have mercy upon us.' Parish watchmen stood outside to keep the sick families locked indoors for forty days.\"\n\n\"It was the very first plague door I had ever seen, and my stomach turned with dread. Fearing I had breathed poisoned air, I hurried into a shop to buy strong roll-tobacco. Smelling and chewing the bitter leaf calmed my fear.\"\n\n\"16 August 1665: Lord! How sad a sight it is to see London’s streets almost empty. Two shops out of every three stand boarded up. Passers-by cross the street in terror whenever they spot a shut door.\"\n\n\"3 September 1665: Grass now grows between the stones in the royal courts at Whitehall. Nightly dead-carts rumble toward deep plague pits, and the weekly Bill of Mortality has passed six thousand dead. Coal fires burn at street corners for three days and nights to cleanse the air, yet still the plague rages through poor parishes.\"",
