      "extract": "At the end of August 1854, terror gripped the crowded Soho lanes around Broad Street in London. Within ten days, over five hundred neighbours died agonising deaths from cholera. Yellow warning flags flapped in the breeze while terrified families piled furniture onto handcarts to flee. Almost every top doctor in Britain blamed \"miasma\"—bad air rising from street drains.\n\nQuiet local doctor John Snow doubted that theory. Convinced that victims swallowed cholera in dirty water, Snow walked Soho’s cobbles with a notebook in hand. Drawing a black bar for every death on a street map, he uncovered a deadly bullseye clustering tightly around the Broad Street water pump.\n\nTwo striking outliers clinched Snow’s detective case. Right next to the pump stood the Lion Brewery, yet zero of its seventy workers had died. Why? They drank a daily allowance of brewery beer and never touched pump water! Nearby, a workhouse holding over five hundred inmates had its own private well and lost barely five residents. Digging later revealed a cracked brick cesspit at 40 Broad Street, where Frances Lewis had rinsed her sick baby’s nappies just three feet from the well! On 8 September, parish officials removed the pump handle.",
