          "question": "Even after parish officials took the handle off the Broad Street pump on 8 September 1854, why did the government’s Medical Board STILL reject Snow’s idea?",
          "answer": "Pasteur’s Germ Theory (1861) and Koch’s microscope proof (1883) did not exist yet, so Snow could prove WHERE cholera spread statistically, but could not show the germ."
