      "extract": "Inside Parliament in July 1858, heavy curtains soaked in lime could no longer block the stench rising off the baking River Thames. Gasping MPs passed a three-million-pound law in just eighteen days. They handed this huge task to Chief Engineer Joseph Bazalgette.\n\nTireless and bold, Bazalgette checked thousands of plans himself and tested every batch of strong Portland cement. Beneath London’s busy streets, teams of diggers built eighty-two miles of giant brick main sewers. Over a thousand miles of smaller street drains fed into them. Built with 318 million bricks, the tunnels caught London’s waste before it reached the river. Huge steam engines at Crossness—and coastal pumps like Eastney in Portsmouth—sent waste far out on the falling tide.\n\nMPs had built Bazalgette’s sewers to stop \"bad smells.\" Yet wherever the brick tunnels opened, water-borne cholera vanished! Soon lab science proved why. Louis Pasteur published Germ Theory in 1861, and Robert Koch found the cholera germ in 1883. Once town workers won the vote in 1867, Parliament passed the 1875 Public Health Act. Clean water and closed sewers became the law for every British town.",
